INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$The facts about the firm's specialty and Dalton's specialty can both be true. There is no contradiction until the author assumes every member shares the firm's primary specialty.$batch01$), ($batch01$B$batch01$, $batch01$Dalton may practice without a firm, but that does not establish he does. The error is ruling out membership based on his specialty.$batch01$), ($batch01$C$batch01$, $batch01$The law firm as a whole primarily does criminal defense. Dalton primarily does divorce. Those facts can coexist with his being a member. A group's dominant trait need not be shared by each member.$batch01$), ($batch01$D$batch01$, $batch01$The conclusion is about Dalton's membership, not whether the firm's criminal-defense wins are evenly spread among attorneys. The 90 percent figure is background.$batch01$), ($batch01$E$batch01$, $batch01$The author does not generalize from a selected subset of lawyers. The error is applying a characteristic of a firm to an individual attorney.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT106-S2-Q2$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
